24	 * Guards owner creation against overfilling a city: a city may hold at most
25	 * {@value #MAX_OWNERS_PER_CITY} owners, so a candidate whose city already contains that
26	 * many is rejected.
27	 */
28	@Component
29	public class CityCapacityValidator {
30	
31	    /** Maximum number of owners allowed to share a single city. */
32	    static final int MAX_OWNERS_PER_CITY = 50;
33	
34	    private final ClinicService clinicService;
35	
36	    public CityCapacityValidator(ClinicService clinicService) {
37	        this.clinicService = clinicService;
38	    }
39	
40	    /**
41	     * Reject {@code candidate} when its city already contains the maximum number of owners.
42	     *
43	     * @param candidate the owner about to be created
44	     * @throws CityCapacityExceededException if the candidate's city is already at capacity
45	     */
46	    public void validate(Owner candidate) {
47	        if (clinicService.countOwnersInCity(candidate.getCity()) >= MAX_OWNERS_PER_CITY) {
48	            throw new CityCapacityExceededException(candidate.getCity(), MAX_OWNERS_PER_CITY);
49	        }
50	    }
